<?php
require_role('admin');
$queues=admin_assignment_queues();$counts=admin_assignment_counts();
$view=(string)($_GET['view']??'review');if(!isset($queues[$view]))$view='review';
$search=trim(substr((string)($_GET['search']??''),0,160));$area=max(0,(int)($_GET['area']??0));
$where=["i.duplicate_of IS NULL",'('.$queues[$view][1].')'];$params=[];
if($search!==''){$where[]='(i.title LIKE ? OR i.address LIKE ? OR i.id=?)';$params[]='%'.$search.'%';$params[]='%'.$search.'%';$params[]=(int)ltrim($search,'#');}
if($area){$where[]='i.area_id=?';$params[]=$area;}
$geo_filters=[];foreach(['province'=>'province_id','district'=>'district_id','town'=>'town_id'] as $key=>$column){$geo_filters[$key]=max(0,(int)($_GET[$key]??0));if($geo_filters[$key]){$where[]='i.'.$column.'=?';$params[]=$geo_filters[$key];}}
$sql=' WHERE '.implode(' AND ',$where);$total=(int)q('SELECT COUNT(*) FROM issues i'.$sql,$params)->fetchColumn();
$pages=max(1,(int)ceil($total/15));$pn=min($pages,max(1,(int)($_GET['p']??1)));
$rows=q(issue_query().$sql." ORDER BY FIELD(i.priority,'High','Medium','Low'),i.created_at,i.id LIMIT 15 OFFSET ".(($pn-1)*15),$params)->fetchAll();
$selected=null;if(!empty($_GET['id']))$selected=q(issue_query().' WHERE i.id=?',[(int)$_GET['id']])->fetch();
admin_page_start('Assign issues','Review new reports, verify assignments and review district workloads.',(bool)$selected);
?><nav class="report-tabs" aria-label="Assignment queues"><?php foreach($queues as $key=>$info):if($key==='unassigned')continue;$label=$info[0];?><a class="report-tab <?=$view===$key?'selected':''?>" href="?<?=e(http_build_query(array_merge(['page'=>'assignments','view'=>$key,'search'=>$search],$geo_filters)))?>"><?=e($label)?> <b><?=$counts[$key]?></b></a><?php endforeach;?></nav>
<section class="panel"><form method="get" class="admin-assignment-filters"><input type="hidden" name="page" value="assignments"><input type="hidden" name="view" value="<?=e($view)?>"><label>Search title, location or ID<input name="search" maxlength="160" value="<?=e($search)?>" placeholder="Title, location or #ID"></label><?php geo_filter_controls($geo_filters);?><button class="button secondary">Filter</button><a class="text-link" href="index.php?page=assignments">Reset</a></form><p class="small muted">Open a submitted report to review its photo, location and details before verification. Tab counts cover your permitted reports; filters narrow the list. Each report can be assigned only to its configured District Officer. <a href="index.php?page=routing">Manage routing responsibility →</a></p></section>
<?php if($selected):$i=$selected;?>
<section class="panel section-space" id="assignment"><h2>Assign report #<?=$i['id']?> · <?=e($i['title'])?></h2><p><?=badge($i['status'])?> · <?=e(($i['province_name']?:'Unclassified').' / '.($i['district_name']?:'—').' / '.($i['town_name']?:'—'))?> · Current officer: <?=e($i['officer']?:'Unassigned')?></p><a class="text-link" href="index.php?page=issue&amp;id=<?=$i['id']?>">Review full report and routing →</a><div class="admin-preview-grid section-space"><div><img class="admin-report-photo" src="media.php?file=<?=e($i['photo'])?>" alt="Report evidence"><p class="small preline"><?=e($i['description'])?></p></div><div><div id="detail-map" class="map-small" data-lat="<?=e($i['latitude'])?>" data-lng="<?=e($i['longitude'])?>"></div><p class="small muted"><?=e($i['address'])?><br><?=e($i['latitude'])?>, <?=e($i['longitude'])?></p></div></div>
<?php if($i['status']==='Submitted' && !$i['duplicate_of']):?><form method="post"><?php csrf();?><input type="hidden" name="action" value="admin_review_issue"><input type="hidden" name="issue_id" value="<?=$i['id']?>"><input type="hidden" name="previous_revision" value="<?=e(assignment_revision($i))?>"><label>Review decision<select name="decision"><option value="Verified">Verify and move to assignment queue</option><option value="Rejected">Reject report</option></select></label><label>Review reason<textarea name="note" minlength="3" maxlength="2000" required></textarea></label><button class="button">Save review</button></form><?php endif;?>
<?php if(!$i['duplicate_of'] && in_array($i['status'],['Verified','Assigned','In Progress'],true)):$district_owner=geo_raw('SELECT officer_id FROM geo_districts WHERE id=?',[$i['district_id']])->fetchColumn();$eligible=array_values(array_filter(officer_workloads(),function($o)use($district_owner){return (int)$o['id']===(int)$district_owner;}));?>
<?php if(!$eligible):?><p class="alert error">No active District Officer is configured for this district. Open Province routing to create or configure the district account.</p><?php else:?>
<form method="post" class="section-space" data-confirm="Save this officer assignment? The officer and reporter will be notified."><?php csrf();?><input type="hidden" name="action" value="assign_officer"><input type="hidden" name="issue_id" value="<?=$i['id']?>"><input type="hidden" name="previous_revision" value="<?=e(assignment_revision($i))?>"><label>Officer · active accounts / open workload<select name="officer_id" required><option value="">Choose an officer</option><?php foreach($eligible as $o):?><option value="<?=$o['id']?>" <?=$i['officer_id']==$o['id']?'selected':''?>><?=e($o['name'])?> · <?=$o['workload']?> open · <?=e($i['district_name']?:'District not configured')?></option><?php endforeach;?></select></label><div class="two-col"><label>Priority<select name="priority"><?php foreach(['Low','Medium','High'] as $v):?><option <?=$i['priority']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></label><label>Due date (optional)<input type="date" name="due_date" value="<?=e($i['due_date'])?>"></label></div><label><?=$i['officer_id']?'Reassignment reason / instructions':'Assignment instructions'?><textarea name="note" minlength="3" maxlength="2000" required placeholder="Instructions for the assigned officer"></textarea></label><p class="small muted">Verified becomes Assigned. Reassigning active work preserves its current status. Open workload includes work awaiting approval.</p><button class="button"><?=$i['status']==='Verified'&&$i['officer_id']?'Confirm assignment':'Save assignment'?></button></form>
<?php endif;else:?><p class="alert">This report cannot be assigned here. Review Submitted reports first. Awaiting approval and closed reports must be handled from the report details.</p><?php endif;?></section>
<?php endif;?>
<section class="panel section-space"><h2><?=$total?> matching issues</h2><?php if(!$rows):?><p class="small muted">No issues match this queue and filters. Review another tab or reset the filters.</p><?php else:?><div class="table-wrap"><table><thead><tr><th>Report / location</th><th>Province / District / Town</th><th>Status / priority</th><th>Officer</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $i):?><tr><td><a class="table-title" href="index.php?page=issue&amp;id=<?=$i['id']?>">#<?=$i['id']?> · <?=e($i['title'])?></a><small><?=e($i['address'])?></small></td><td><?=e(($i['province_name']?:'Not classified').' / '.($i['district_name']?:'Not classified').' / '.($i['town_name']?:'Not classified'))?></td><td><?=badge($i['status'])?><small><?=e($i['priority'])?> priority</small></td><td><?=e($i['officer']?:'Unassigned')?></td><td><?php if($i['status']==='Submitted'):?><a class="button secondary" href="index.php?page=assignments&amp;view=review&amp;id=<?=$i['id']?>#assignment">Review first</a><?php else:?><a class="button secondary" href="?<?=e(http_build_query(array_merge(['page'=>'assignments','view'=>$view,'search'=>$search,'p'=>$pn,'id'=>$i['id']],$geo_filters)))?>#assignment"><?=$i['officer_id']?'Reassign':'Assign'?></a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?><?php admin_pager($pn,$pages,$total);?></section><?php admin_page_end();
